def p58():
    b = Builder()
    P(b, [('From this it becomes known that, to see the correct picture of the foreign trade of some country, instead of the balance of trade we should see its balance of payments, in which visible and invisible things are all included.', 'اس سے پتہ چلتا ہے کہ ہمیں کسی ملک کی بیرونی تجارت کی صحیح تصویر دیکھنے کے لیے توازنِ تجارت کے بجائے اس کا توازنِ ادائیگیاں دیکھنا چاہیے جس میں مرئی اور غیر مرئی سب چیزیں شامل ہوتی ہیں۔', 'له دې معلومېږي چې د یوه هېواد د بهرنۍ سوداګرۍ د سم انځور د لیدو لپاره باید د سوداګرۍ د توازن پر ځای د هغه د تادیو توازن وګورو چې لیدونکي او نالیدونکي ټول شیان پکې شامل وي.')])
    b.h('Definition of balance of trade (Definition of Balacne of Trade)', 'توازنِ تجارت کی تعریف: (Definition of Balacne of Trade)', 'د سوداګرۍ د توازن تعریف (Definition of Balacne of Trade)')
    P(b, [('The balance of trade can be defined thus:', 'توازنِ تجارت کی تعریف یوں کی جا سکتی ہے:', 'د سوداګرۍ توازن داسې تعریفېدای شي:'),
          ('“That part of the balance of payments of a nation (or country) which relates only to the imports and exports of merchandise (Merchandise) or visible (i.e. seen) goods (Visible).”', '”کسی قوم (یا ملک) کی ادائیگیوں کے توازن کا وہ حصہ جس کا تعلق صرف اشیائے تجارت (Merchandise) یا مرئی (یعنی نظر آنے والی اشیاء کی) (Visible) درآمدات و برآمدات سے ہو۔“', '”د یوه ملت (یا هېواد) د تادیو د توازن هغه برخه چې یوازې د سوداګریزو توکو (Merchandise) یا لیدونکو (یعنې ښکاره) توکو (Visible) له واردولو او صادرولو سره تړاو ولري.“')])
    b.h('Balance of payments (Balance of Payments)', 'ادائیگیوں کا توازن (Balance of Payments):', 'د تادیو توازن (Balance of Payments)')
    P(b, [('By the balance of payments is meant such a record from which it becomes known how many goods and services in total some country has imported and how many goods and services it has exported. As it were, in the balance of payments both kinds of heads, visible and invisible, are kept in view. Professor Kindleberger (C.P. Kindleberger) defines the balance of payments in this way:', 'ادائیگیوں کے توازن سے مراد ایسا ریکارڈ ہے جس سے پتہ چلتا ہے کہ کسی ملک نے مجموعی طور پر کتنی اشیاء و خدمات درآمد کی ہیں اور کتنی اشیاء و خدمات برآمد کی ہیں، گویا ادائیگیوں کے توازن میں مرئی اور غیر مرئی دونوں قسم کی مدوں کو پیشِ نظر رکھا جاتا ہے۔ پروفیسر کنڈل برگر (C.P. Kindleberger) ادائیگیوں کے توازن کی تعریف اس طرح کرتے ہیں:', 'له تادیو توازن مراد داسې ریکارډ دی چې له هغه معلومېږي چې یوه هېواد په ټولیز ډول څومره توکي او خدمتونه وارد کړي او څومره توکي او خدمتونه صادر کړي دي. ګواکې د تادیو په توازن کې لیدونکي او نالیدونکي دواړه ډوله سرونه په پام کې نیول کېږي. پروفېسر کنډلبرګر (C.P. Kindleberger) د تادیو توازن داسې تعریفوي:'),
          ('“By it is meant that regular record of all economic transactions which takes place between the residents of one country and the residents of foreign countries.”', '”اس سے مراد تمام معاشی لین دین کا باقاعدہ ریکارڈ ہے جو ایک ملک کے باشندوں اور بیرونی ممالک کے باشندوں کے درمیان ہوتا ہے۔“', '”له دې مراد د ټولو اقتصادي راکړو ورکړو منظم ریکارډ دی چې د یوه هېواد د اوسېدونکو او د بهرنیو هېوادونو د اوسېدونکو ترمنځ کېږي.“'),
          ('Professor David Begg (David Begg) defines the balance of payments thus:', 'پروفیسر ڈیوڈ بیگ (David Begg) ادائیگیوں کے توازن کی تعریف یوں کرتے ہیں:', 'پروفېسر ډېویډ بېګ (David Begg) د تادیو توازن داسې تعریفوي:')])
    b.p('"The balance of payments record transactions between residents of one country and the rest of the world."', '"The balance of payments record transactions between residents of one country and the rest of the world."', '"The balance of payments record transactions between residents of one country and the rest of the world."')
    b.paras[-1]['untranslatedByDesign'] = True
    b.h('Items of the balance of payments (Items)', 'ادائیگیوں کے توازن کی مدیں (Items):', 'د تادیو د توازن سرونه (Items)')
    P(b, [('In the balance of payments of a country, besides visible goods (Visible), i.e. common things, the following invisible goods (Invisible), i.e. services, are also included.', 'کسی ملک کی ادائیگیاں کے توازن میں مرئی اشیاء (Visible) یعنی عام چیزوں کے علاوہ مندرجہ ذیل غیر مرئی اشیاء (Invisible) یعنی خدمات بھی شامل کی جاتی ہیں۔', 'د یوه هېواد د تادیو په توازن کې له لیدونکو توکو (Visible)، یعنې عامو شیانو پرته، لاندې نالیدونکي توکي (Invisible)، یعنې خدمتونه هم شاملېږي.')])
    H(b, 1, 'Remuneration for the services of foreign companies', 'غیر ملکی کمپنیوں کی خدمات کا معاوضہ', 'د بهرنیو شرکتونو د خدمتونو معاوضه')
    P(b, [('In connection with foreign trade every country obtains the services of the insurance companies, ships, banks, commission agents (Commission Agents) and brokers (Brokers) of other countries and pays them remuneration, and sometimes it itself provides such services to other countries and receives remuneration for them. As it were, these services too are exported and imported.', 'بیرونی تجارت کے سلسلہ میں ہر ملک دوسرے ملک کی بیمہ کمپنیوں، جہازوں، بنکوں، آڑھتیوں (Commission Agents)، دلالوں (Brokers) کی خدمات حاصل کرتا ہے اور انہیں معاوضہ ادا کرتا ہے اور کبھی خود دوسرے ملکوں کی ایسی خدمات مہیا کرتا ہے اور اس کی معاوضہ وصول کرتا ہے۔ گویا یہ خدمات بھی برآمد اور درآمد کی جاتی ہیں۔', 'د بهرنۍ سوداګرۍ په برخه کې هر هېواد د نورو هېوادونو د بیمې شرکتونو، بېړیو، بانکونو، کمیشن‌کارانو (Commission Agents) او دلالانو (Brokers) خدمتونه ترلاسه کوي او معاوضه ورکوي، او کله پخپله نورو هېوادونو ته داسې خدمتونه برابروي او معاوضه یې اخلي. ګواکې دا خدمتونه هم صادرېږي او واردېږي.')])
    H(b, 2, 'Expenses of tourism', 'سیر و سیاحت کے اخراجات', 'د سیل او سیاحت لګښتونه')
    P(b, [('The residents of different countries come and go to other countries for recreation and spend money there. Sometimes it happens that fewer people come from outside to see a country, but the residents of that country itself go in greater numbers to see other countries; therefore it does not receive as much sum as its residents spend going outside. This thing too can become the cause of spoiling its balance of payments.', 'مختلف ملکوں کے باشندے، سیر و تفریح کے لیے دوسرے ممالک میں آتے جاتے ہیں اور وہاں روپیہ خرچ کرتے ہیں، بعض اوقات ایسا ہوتا ہے کہ ایک ملک دیکھنے کے لیے باہر سے کم لوگ آتے ہیں لیکن خود اس ملک کے بہت زیادہ باشندے دوسرے ملکوں کی سیر کو جاتے ہیں۔ اس لیے اسے اتنی رقم وصول نہیں ہوتی جتنی یہاں کے باشندے باہر جا کر خرچ کر آتے ہیں۔ یہ بات بھی اس کے ادائیگیوں کے توازن کو خراب کرنے کا باعث بن سکتی ہے۔', 'د بېلابېلو هېوادونو اوسېدونکي د سیل او تفریح لپاره نورو هېوادونو ته ځي راځي او هلته پیسې لګوي. کله کله داسې کېږي چې د یوه هېواد د لیدو لپاره له بهره لږ خلک راځي، خو پخپله د هغه هېواد ډېر اوسېدونکي د نورو هېوادونو سیل ته ځي؛ نو ورته هومره پیسې نه رسېږي څومره چې د دې ځای اوسېدونکي بهر لګوي. دا خبره هم د هغه د تادیو د توازن د خرابېدو لامل کېدای شي.')])
    H(b, 3, 'Expenses of education in other countries', 'دوسرے ملکوں میں تعلیم کے اخراجات', 'په نورو هېوادونو کې د زده‌کړې لګښتونه')
    P(b, [('The residents of different countries obtain education in some other country and spend money there. Therefore in the balance of payments the heads of expenditure and income of this kind too are entered; e.g. some students from Pakistan go to Oxford, Cambridge and American universities to obtain education and spend money there. In the same way students from Saudi Arabia, Yemen, the United Arab Emirates (UAE) and other countries … (continued on p.97)', 'مختلف ملکوں کے باشندے کسی دوسرے ملک میں تعلیم حاصل کرتے ہیں اور وہاں روپیہ خرچ کرتے ہیں۔ چنانچہ ادائیگیوں کے توازن میں اس قسم کے خرچ اور آمدنی کی مدیں بھی درج ہوتی ہیں، مثلاً پاکستان سے کچھ طلبہ، آکسفورڈ، کیمبرج اور امریکی یونیورسٹیوں میں تعلیم حاصل کرنے جاتے ہیں، اور وہاں روپیہ خرچ کرتے ہیں۔ اسی طرح سعودی عرب، یمن، متحدہ عرب امارات (UAE) اور دیگر ممالک کے … (ص 97 پر جاری)', 'د بېلابېلو هېوادونو اوسېدونکي په کوم بل هېواد کې زده‌کړه کوي او هلته پیسې لګوي. نو د تادیو په توازن کې د دې ډول لګښت او عاید سرونه هم لیکل کېږي؛ لکه له پاکستانه ځینې زده‌کوونکي اکسفورډ، کمبرج او امریکايي پوهنتونونو ته د زده‌کړې لپاره ځي او هلته پیسې لګوي. همداسې د سعودي عربستان، یمن، متحده عربي اماراتو (UAE) او نورو هېوادونو … (په ۹۷ مخ دوام لري)')])
    r1 = rec(b, 5, 15, 58, pages_=[96])
